(()=>{function install(){if(document.querySelector('[data-weather-history-link]'))return;const panel=document.querySelector('#observationPanel .panel-head');if(panel){const a=document.createElement('a');a.href='/weather-history.html';a.dataset.weatherHistoryLink='1';a.textContent='Lịch sử & so sánh ↗';a.style.cssText='display:inline-flex;align-items:center;margin-left:auto;margin-right:8px;padding:7px 9px;border-radius:10px;background:#eaf6fd;color:#0877ad;text-decoration:none;font:650 9px Inter,ui-sans-serif,sans-serif;white-space:nowrap';const kicker=panel.querySelector('#nowcastKicker');panel.insertBefore(a,kicker||null)}const dock=document.querySelector('.app-dock');if(dock&&!dock.querySelector('[data-weather-history-dock]')){const b=document.createElement('button');b.type='button';b.className='has-svg';b.dataset.weatherHistoryDock='1';b.setAttribute('aria-label','Lịch sử Weather Lab');b.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/></svg><span>Lịch sử</span>';b.addEventListener('click',()=>location.href='/weather-history.html');dock.appendChild(b);dock.classList.add('has-history')}}window.WeatherLabHistoryLink={install};})();
